"""Camera/proprioception-only controller for the single StockingBreakfastFoods episode."""
import json, sys, time
from pathlib import Path
import numpy as np
from scipy.spatial.transform import Rotation as Rot
from scipy.optimize import least_squares
from rcb_client import Robot
ROOT=Path('/app/output'); RUNS=Path('/app/runs')
r=Robot()

def save(obs,name):
 obs.save(str(RUNS/name)); (ROOT/'latest.txt').write_text(name)
 print(name, 'time',obs.meta['time_left_s'], 'eef',np.array(obs.meta['proprio']['now'])[26:29],flush=True)
 return obs

def observe(name='obs'):
 return save(r.get_obs(include_depth=True,video='none'),name)

def latest():return json.loads((RUNS/(ROOT/'latest.txt').read_text()/'meta.json').read_text())

def move(q=None,grip=None,base=None,torso=0,n=40,name='move'):
 m=latest(); p=np.array(m['proprio']['now']); a=p[29:42].copy(); a[8:12]=0; a[12]=-1
 start=p[4:11]; target=start if q is None else np.array(q)
 if grip is not None:a[7]=grip
 if base is not None:a[8:11]=base;a[12]=1
 a[11]=torso
 A=np.tile(a,(n,1)); A[:,:7]=np.linspace(start,target,n)
 obs=r.submit('joint_position',A,cameras=None,include_depth=True,video='none',note=name)
 return save(obs,name)

def fk(q):
 T=np.eye(4)
 xyz=[(0,0,.333),(0,0,0),(0,-.316,0),(.0825,0,0),(-.0825,.384,0),(0,0,0),(.088,0,0)]
 rx=[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2]
 for v,x,t in zip(xyz,rx,q):
  A=np.eye(4);A[:3,3]=v;A[:3,:3]=Rot.from_euler('x',x).as_matrix()@Rot.from_euler('z',t).as_matrix();T=T@A
 return T

def fit():
 ms=[json.loads(p.read_text()) for p in sorted(RUNS.glob('cal*/meta.json'))]
 def residual(v):
  B=Rot.from_rotvec(v[:3]).as_matrix();t=v[3:6];g=v[6:9]; C=Rot.from_rotvec(v[9:12]).as_matrix();errs=[]
  for m in ms:
   p=np.array(m['proprio']['now']);T=fk(p[4:11]);W=np.array(m['cameras']['robot0_eye_in_hand']['cam2world_gl']);
   errs.extend((B@(T[:3,3]+T[:3,:3]@g)+t-p[26:29])*10)
   errs.extend(Rot.from_matrix((B@T[:3,:3]@C).T@W[:3,:3]).as_rotvec())
  return errs
 v=np.zeros(12);v[2]=np.pi/2;v[3:6]=[7.2,-1,0.8];v[8]=.2
 out=least_squares(residual,v,max_nfev=2000)
 print('fit',out.x,'error',np.linalg.norm(out.fun))
 np.save(ROOT/'kin.npy',out.x)

def kin(q):
 v=np.load(ROOT/'kin.npy');B=Rot.from_rotvec(v[:3]).as_matrix(); T=fk(q)
 return B@(T[:3,3]+T[:3,:3]@v[6:9])+v[3:6], B@T[:3,:3]@Rot.from_rotvec(v[9:12]).as_matrix()

def ik(pos,R=None):
 p=np.array(latest()['proprio']['now']); q0=p[4:11]
 if R is None:R=kin(q0)[1]
 def fun(q):
  x,M=kin(q);return np.r_[10*(x-pos),Rot.from_matrix(R.T@M).as_rotvec(),.015*(q-q0)]
 opt=least_squares(fun,q0,bounds=([-2.85,-1.75,-2.85,-3.05,-2.85,-.01,-2.85],[2.85,1.75,2.85,-.07,2.85,3.75,2.85]),max_nfev=500)
 print('ik error',fun(opt.x)[:6], 'q',opt.x,flush=True)
 return opt.x

def goto(pos,R=None,n=40,grip=None,name='goto'):return move(ik(np.array(pos),R),n=n,grip=grip,name=name)

def point(u,v,cam='robot0_eye_in_hand',name=None):
 name=name or (ROOT/'latest.txt').read_text();m=json.loads((RUNS/name/'meta.json').read_text()); D=np.load(RUNS/name/f'depth_{cam}.npy');D=D[-1] if D.ndim==3 else D
 c=m['cameras'][cam];K=np.array(c['intrinsic_cv']);T=np.array(c['cam2world_gl']);d=float(D[v,u]);xyz=np.array([(u-K[0,2])/K[0,0]*d,-(v-K[1,2])/K[1,1]*d,-d]);return T[:3,:3]@xyz+T[:3,3]

if __name__=='__main__':
 cmd=sys.argv[1] if len(sys.argv)>1 else 'observe'
 if cmd=='observe':observe(sys.argv[2] if len(sys.argv)>2 else 'obs')
 if cmd=='calibrate':
  obs=observe('cal0');q=np.array(obs.meta['proprio']['now'])[4:11]
  for i in range(7):
   qt=q.copy();qt[i]+=.10
   move(qt,n=25,name=f'cal{i+1}')
   move(q,n=25,name=f'return{i+1}')
  fit()
 if cmd=='fit':fit()
